_SUPABASE_AVAILABILITY_REFRESH: dict[str, asyncio.Task] = {}
def _kick_availability_refresh(self, config) -> None:
    key = config.url.rstrip("/")
    task = _SUPABASE_AVAILABILITY_REFRESH.get(key)
    if task is not None and not task.done():
        return
    async def _refresh() -> None:
        try:
            client = await self._get_client(config.timeout_s)
            await self._probe_data_api(client=client, config=config)
        except Exception:
            pass  # 结果(True/False)已在 probe 体内写缓存;402 raise 在此吞掉
    _SUPABASE_AVAILABILITY_REFRESH[key] = asyncio.create_task(_refresh(), context=contextvars.Context())
```
